import {seeds,escapeHTML as e,safeURL,advance,stages} from './domain.mjs';
import {storefront,heroArt} from './art.mjs';
import {aiState,enableAI,generateBrief,reviewCaption} from './ai.mjs';
const key='localperks-v1';
let state={campaigns:structuredClone(seeds),applications:[],saved:[]};
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved&&Array.isArray(saved.campaigns)&&Array.isArray(saved.applications)&&Array.isArray(saved.saved))state=saved;}catch{}
let role='creator',view='explore',category='All',reward='All rewards',city='All cities',search='',savedOnly=false,draft=null;
let partners={backboard:false,shared:false};
const $=s=>document.querySelector(s),modal=$('#modal'),main=$('#main');
const icon='↗';
function persist(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('Browser storage is full. Export your workspace before closing.');}updateCount();}
function updateCount(){$('#workspace-count').textContent=state.applications.length?`(${state.applications.length})`:'';}
let toastTimer;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('visible'),4200);}
function openModal(title,content){$('#modal-content').innerHTML=`<div class="modal-inner"><div class="modal-top"><h2>${e(title)}</h2><button class="close" data-action="close" aria-label="Close dialog">×</button></div>${content}</div>`;if(!modal.open)modal.showModal();}
function card(c){return `<article class="card"><div class="card-image">${storefront(c.art,c.color)}<span class="card-label">${e(c.category)}</span><button class="bookmark ${state.saved.includes(c.id)?'saved':''}" data-action="save" data-id="${e(c.id)}" aria-label="${state.saved.includes(c.id)?'Unsave':'Save'} ${e(c.title)}" aria-pressed="${state.saved.includes(c.id)}">${state.saved.includes(c.id)?'♥':'♡'}</button></div><div class="card-body"><div class="business-line"><span class="business-icon">⌂</span>${e(c.business)}<span>·</span>${e(c.city)}</div><h3>${e(c.title)}</h3><p class="card-desc">${e(c.description)}</p><div class="tags"><span class="tag">${e(c.platform)}</span><span class="tag">${c.deliverables.length} deliverables</span><span class="tag">${c.sample?'Sample opportunity':'Your opportunity'}</span></div><div class="card-bottom"><div class="reward">${e(c.reward)}<small>Agreed reward · no platform payout</small></div><button class="arrow-button" data-action="details" data-id="${e(c.id)}" aria-label="View ${e(c.title)}">${icon}</button></div></div></article>`;}
function filtered(){return state.campaigns.filter(c=>(category==='All'||c.category===category)&&(reward==='All rewards'||c.rewardType===reward)&&(city==='All cities'||c.city===city)&&(!savedOnly||state.saved.includes(c.id))&&`${c.title} ${c.business} ${c.city} ${c.description}`.toLowerCase().includes(search.toLowerCase()));}
function renderCards(){const list=filtered();$('#cards').innerHTML=list.length?list.map(card).join(''):`<div class="empty"><h3>No opportunities here yet.</h3><p>Try a different city or category, or create your first opportunity.</p><button class="button" data-action="new">Create an opportunity ${icon}</button></div>`;$('#result-count').textContent=`${list.length} ${list.length===1?'opportunity':'opportunities'}${savedOnly?' saved':''}`;}
function roleSwitch(){return `<div class="role-switch"><button class="${role==='creator'?'selected':''}" data-role="creator">✧ I’m a creator</button><button class="${role==='business'?'selected':''}" data-role="business">⌂ I’m a business</button></div>`;}
function render(){updateCount();document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('active',n.dataset.view===view));if(view==='workspace'){renderWorkspace();return;}
main.innerHTML=`<section class="hero"><div><div class="eyebrow"><span></span>Small businesses. Big local energy.</div><h1>Create something<br><em>close to home.</em></h1><p>Your favorite neighborhood spots need your kind of creativity. Find local collaborations. Make good content. Get rewarded.</p><button class="button" data-action="browse">Find your next collaboration <span>↓</span></button><div class="hero-foot">For the café down the street. And the creator around the corner.</div></div><div class="hero-art"><div class="floating-note">♡ Made for your neighborhood</div>${heroArt()}<div class="floating-note right">Good content. Good company. ✳</div></div></section><div class="switch-row">${roleSwitch()}<span class="small-note">A small following can make a big local difference.</span></div><section id="opportunities"><div class="section-title"><div><h2>${role==='business'?'Find inspiration. Start a collaboration.':'Your neighborhood, your next opportunity.'}</h2><p>${role==='business'?'Turn your next promotion into a clear creator brief.':'Discover small businesses looking for someone just like you.'}</p></div><button class="button ${role==='business'?'primary':'secondary'}" data-action="new">Create an opportunity <span>+</span></button></div><div class="filters"><div class="search"><span aria-hidden="true">⌕</span><input id="search" type="search" aria-label="Search opportunities" placeholder="Search businesses, neighborhoods, or ideas…" value="${e(search)}"></div><select class="filter" id="city" aria-label="Filter by city">${['All cities',...new Set(state.campaigns.map(c=>c.city))].map(x=>`<option ${city===x?'selected':''}>${e(x)}</option>`).join('')}</select><select class="filter" id="reward" aria-label="Filter by reward">${['All rewards','Cash + perks','Cash','Perks'].map(x=>`<option ${reward===x?'selected':''}>${e(x)}</option>`).join('')}</select><div class="filter-wrap">${['All','Food & drink','Shops & makers','Wellness'].map(x=>`<button class="chip ${category===x?'active':''}" data-category="${e(x)}">${e(x)}</button>`).join('')}</div></div><div class="results-line"><span id="result-count"></span><button class="text-button" data-action="saved">${savedOnly?'Show all opportunities':'♡ Saved opportunities'}</button></div><div class="grid" id="cards"></div></section><section class="local-strip"><div><h3>Your business. Their creativity. A good match.</h3><p>Tell us what you’re planning. Turn it into a brief creators can act on.</p></div><button class="button" data-action="new">Create your first opportunity ${icon}</button></section>`;renderCards();}
function details(id){const c=state.campaigns.find(x=>x.id===id);if(!c)return;const applied=state.applications.some(x=>x.campaignId===id);openModal(c.title,`<div class="modal-image">${storefront(c.art,c.color)}</div><p class="modal-intro">${e(c.business)} · ${e(c.city)}${c.sample?' · Sample business':''}</p><p class="modal-intro">${e(c.description)}</p><div class="details-grid"><div><small>REWARD</small>${e(c.reward)}</div><div><small>PLATFORM</small>${e(c.platform)}</div><div><small>DEADLINE</small>${e(c.deadline)}</div></div><h3>What you’ll create</h3><ul class="detail-list">${c.deliverables.map(x=>`<li>${e(x)}</li>`).join('')}</ul><div class="callout">Agree on the scope, reward, content usage, and timing with the business before starting. This prototype tracks the agreement; it does not hold funds, send payments, or verify reach.</div><div class="actions">${role==='business'?`<button class="button secondary" data-action="workspace">Manage collaborations</button>`:`<button class="button primary" data-action="apply" data-id="${e(id)}" ${applied?'disabled':''}>${applied?'Application saved':'Apply for this collaboration'} ${icon}</button>`}</div>`);}
function apply(id){const c=state.campaigns.find(x=>x.id===id);openModal('Make your introduction.',`<p class="modal-intro">Apply to ${e(c.business)} for “${e(c.title)}”. Your application is saved in this browser for the demo.</p><form id="apply-form" data-id="${e(id)}"><div class="form-grid"><div><label for="creator">Your name</label><input id="creator" name="creator" required maxlength="80" placeholder="Alex Rivera"></div><div><label for="handle">Creator handle</label><input id="handle" name="handle" required maxlength="80" placeholder="@alexaroundtown"></div></div><label for="pitch">What would you create?</label><textarea id="pitch" name="pitch" required maxlength="1200" placeholder="I’d love to make a neighborhood guide featuring your business…"></textarea><label class="check-row"><input type="checkbox" required>I understand the listed deliverables and reward. Final terms still need agreement with the business.</label><div class="actions"><button class="button primary" type="submit">Save application ${icon}</button></div></form>`);}
function renderWorkspace(){const own=state.applications;main.innerHTML=`<div class="page-heading"><div class="eyebrow"><span></span>Your collaboration desk</div><h1>Good things in the works.</h1><p>Follow every collaboration from first hello to approved work. Switch roles to walk through the demo.</p></div><div class="switch-row">${roleSwitch()}<button class="button secondary" data-action="export">Export workspace ↓</button></div>${own.length?own.map(a=>{const c=state.campaigns.find(x=>x.id===a.campaignId);if(!c)return '';return `<article class="workspace-item"><div class="item-head"><div><h3>${e(c.title)}</h3><p class="item-meta">${e(c.business)} · ${e(a.creator)} (${e(a.handle)}) · ${e(c.reward)}</p></div><span class="status">${e(a.status)}</span></div><p class="pitch">${e(a.pitch)}</p><div class="stepper">${stages.map((s,i)=>`<span class="${i<=stages.indexOf(a.status)?'done':''}">${i<stages.indexOf(a.status)?'✓':i+1} ${e(s)}</span>`).join('<span aria-hidden="true">→</span>')}</div>${a.submission?`<div class="mini-panel">Submitted work: <a href="${e(safeURL(a.submission)||'#')}" target="_blank" rel="noopener noreferrer">Open work ↗</a>\nCaption: ${e(a.caption||'No caption supplied.')}</div>`:''}${a.review?`<div class="mini-panel">Gemma’s advisory caption review\n${e(a.review)}</div>`:''}${a.status==='Approved'?`<div class="callout">Work approved by the business in this demo. Reward: ${e(c.reward)}. ${a.rewardDelivered?'Business marked the reward as delivered.':'Reward delivery is still pending and happens outside LocalPerks.'}</div>`:''}<div class="actions">${role==='business'&&a.status==='Applied'?`<button class="button primary" data-action="advance" data-next="Accepted" data-id="${e(a.id)}">Accept application</button>`:''}${role==='creator'&&a.status==='Accepted'?`<button class="button primary" data-action="submit-work" data-id="${e(a.id)}">Submit your work ${icon}</button>`:''}${role==='business'&&a.status==='Work submitted'?`<button class="button secondary" data-action="review" data-id="${e(a.id)}">✧ Review caption with Gemma</button><button class="button primary" data-action="advance" data-next="Approved" data-id="${e(a.id)}">Approve work</button>`:''}${role==='business'&&a.status==='Approved'&&!a.rewardDelivered?`<button class="button secondary" data-action="reward-delivered" data-id="${e(a.id)}">Mark reward as delivered</button>`:''}<button class="text-button" data-action="details" data-id="${e(c.id)}">View agreed brief</button></div></article>`}).join(''):`<div class="empty"><h3>Your next collaboration starts with hello.</h3><p>Explore an opportunity and apply as a creator. Then switch to business mode to manage the application.</p><button class="button primary" data-action="explore">Explore opportunities ${icon}</button></div>`}`;}
function newBrief(){draft=null;openModal('A little idea. A clear brief.',`<p class="modal-intro">Tell creators what you’re planning and what’s in it for them. Gemma can help turn your idea into clear deliverables.</p><form id="brief-form"><div class="form-grid"><div><label for="business">Business name</label><input id="business" name="business" required maxlength="80" placeholder="Your neighborhood business"></div><div><label for="location">City & state</label><input id="location" name="city" required maxlength="80" value="Chicago, IL"></div></div><label for="idea">What would you like to promote?</label><textarea id="idea" name="idea" required maxlength="1500" placeholder="We’re a small café launching a new fall menu. We’d love a local creator to visit, try a drink, and share their honest experience…"></textarea><div class="form-grid"><div><label for="compensation">Exact reward</label><input id="compensation" name="reward" required maxlength="100" placeholder="$75 + two drinks"></div><div><label for="deadline">Work due</label><input id="deadline" name="deadline" type="date" min="${new Date().toLocaleDateString('en-CA')}" required></div><div><label for="platform">Platform</label><select id="platform" name="platform"><option>Instagram</option><option>TikTok</option><option>YouTube</option></select></div><div><label for="category">Category</label><select id="category" name="category"><option>Food & drink</option><option>Shops & makers</option><option>Wellness</option></select></div><div><label for="reward-type">Reward type</label><select id="reward-type" name="rewardType"><option>Cash + perks</option><option>Cash</option><option>Perks</option></select></div></div><div class="callout lavender">✧ Local AI: ${aiState.ready?'Gemma is ready on this device.':'Enable Gemma in Open AI & privacy first. The manual template works without AI.'}</div><div id="brief-status" class="ai-status" role="status"></div><div class="actions"><button class="button secondary" type="submit" name="mode" value="manual">Use manual template</button><button class="button primary" type="submit" name="mode" value="ai">✧ Draft with Gemma</button></div></form>`);}
function editDraft(){openModal('Make the brief yours.',`<p class="modal-intro">${draft.ai?'Drafted by Gemma on your device.':'Manual template — no AI was used.'} Review every detail before adding this opportunity.</p><form id="publish-form"><label for="title">Opportunity title</label><input id="title" name="title" required maxlength="120" value="${e(draft.title)}"><label for="description">Description</label><textarea id="description" name="description" required maxlength="2000">${e(draft.description)}</textarea><label for="deliverables">Deliverables — one per line</label><textarea id="deliverables" name="deliverables" required maxlength="2400">${e(draft.deliverables.join('\n'))}</textarea>${draft.questions?.length?`<div class="callout">Confirm before you collaborate:<ul>${draft.questions.map(x=>`<li>${e(x)}</li>`).join('')}</ul></div>`:''}<div class="mini-panel">${e(draft.business)} · ${e(draft.city)}\nReward: ${e(draft.reward)}\nDue: ${e(draft.deadline)} · ${e(draft.platform)}</div><label class="check-row"><input type="checkbox" required>I’ve checked the reward, deliverables, and deadline. This adds an opportunity to this browser’s demo workspace.</label><div class="actions"><button class="button primary" type="submit">Add opportunity ${icon}</button></div></form>`);}
function settings(){openModal('Open AI. Your device.',`<p class="modal-intro">Gemma writes campaign briefs and reviews submitted caption text, using the open-source WebLLM engine in your browser.</p><div class="callout">Your campaign prompts are processed locally by Gemma. Enabling AI downloads approximately 1.5–2 GB of model files from third-party hosts and may take several minutes. You need a WebGPU-capable desktop browser and enough device memory. The model is cached where the browser permits.</div><div class="badge">Gemma 2 · 2B · 4-bit</div><p class="ai-status" id="ai-status" role="status">${e(aiState.message)}</p><progress class="progress" id="ai-progress" value="${aiState.progress}" max="1" aria-label="Model download progress"></progress><div class="actions"><button class="button primary" data-action="enable-ai" ${aiState.loading||aiState.ready?'disabled':''}>${aiState.ready?'Gemma is ready':aiState.loading?'Loading Gemma…':'Download & enable Gemma'}</button></div><hr class="divider"><h3>Campaign memory with Backboard</h3><p class="form-hint">${partners.backboard?'Backboard is connected on this server. Open a collaboration and use campaign memory to save context and ask follow-up questions.':'Backboard is not connected in this preview. The Render server includes a secure integration; set BACKBOARD_API_KEY there to enable persistent campaign conversations.'} Backboard sends entered campaign context to its hosted service when you explicitly use it.</p><button class="button secondary" data-action="memory">Open campaign memory</button><hr class="divider"><h3>Your demo workspace</h3><p class="form-hint">Sample listings are fictional. This is a single-browser prototype with role switching, not authenticated accounts or a live shared marketplace. Applications, briefs, and statuses persist in local browser storage. Nothing is paid automatically.</p><div class="actions"><button class="button secondary" data-action="export">Export workspace ↓</button><button class="text-button" data-action="reset">Reset sample workspace</button></div><p class="form-hint"><a href="https://ai.google.dev/gemma/terms" target="_blank" rel="noopener">Gemma terms</a> · <a href="https://webllm.mlc.ai/" target="_blank" rel="noopener">WebLLM</a> · External fonts and model downloads require an internet connection.</p>`);}
function about(){openModal('Good neighbors. Clear agreements.',`<p class="modal-intro">LocalPerks helps neighborhood businesses and creators turn a small promotion into a manageable collaboration.</p><ol class="detail-list"><li><strong>Business:</strong> describe your idea, exact reward, and deadline. Use Gemma to draft deliverables or write them yourself.</li><li><strong>Creator:</strong> explore opportunities and apply with your idea.</li><li><strong>Business:</strong> accept an application after agreeing on the scope.</li><li><strong>Creator:</strong> submit a work link and the caption.</li><li><strong>Business:</strong> review the actual content, approve the work, and arrange the reward directly.</li></ol><div class="callout lavender">Try both sides: apply to a sample listing, open My collaborations, and switch to business mode to accept. Switch back to creator mode to submit work.</div><p class="form-hint">Gemma’s caption review is advisory and text-only. It cannot inspect linked media, confirm posting, verify performance, or authorize payment.</p><div class="actions"><button class="button primary" data-action="close">Let’s explore ${icon}</button></div>`);}
function submitWork(id){openModal('Show what you created.',`<form id="work-form" data-id="${e(id)}"><label for="work-url">Public link to your work</label><input id="work-url" type="url" name="submission" required placeholder="https://www.instagram.com/reel/…"><label for="caption">Caption or written content</label><textarea id="caption" name="caption" maxlength="4000" required placeholder="Paste the exact caption so the business can review it alongside your link."></textarea><p class="form-hint">The business reviews the linked work. Gemma can only help review the text you enter here.</p><div class="actions"><button class="button primary">Save submitted work ${icon}</button></div></form>`);}
async function memory(){openModal('A memory for your campaign.',`<p class="modal-intro">Save campaign context and keep a conversation with Backboard. Use business-approved details; text entered here is sent to Backboard when you submit.</p><form id="memory-form"><label for="memory-campaign">Campaign</label><select id="memory-campaign" name="campaignId">${state.campaigns.map(c=>`<option value="${e(c.id)}">${e(c.business)} — ${e(c.title)}</option>`).join('')}</select><label for="memory-question">What would you like to remember or ask?</label><textarea id="memory-question" name="question" required maxlength="2000" placeholder="Remember that we prefer a relaxed tone. What should we clarify before accepting a creator?"></textarea><div id="memory-status" class="ai-status" role="status"></div><div id="memory-result" class="review-text"></div><div class="actions"><button class="button primary" ${!partners.backboard?'disabled':''}>Ask campaign memory ${icon}</button></div></form>${!partners.backboard?'<p class="form-hint">Connect Backboard on the Render server to enable this feature. No simulated answers are displayed.</p>':''}`);}
document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b)return;
 if(b.dataset.role){role=b.dataset.role;render();return;}
 if(b.dataset.view){view=b.dataset.view;render();return;}
 if(b.dataset.category){category=b.dataset.category;render();return;}
 const action=b.dataset.action,id=b.dataset.id;
 if(action==='close'){modal.close();return;}
 if(action==='about')return about();if(action==='settings')return settings();if(action==='memory')return memory();
 if(action==='new')return newBrief();if(action==='details')return details(id);if(action==='apply')return apply(id);if(action==='submit-work')return submitWork(id);
 if(action==='browse'){$('#opportunities')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});return;}
 if(action==='workspace'||action==='explore'){modal.close();view=action;render();return;}
 if(action==='save'){state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();renderCards();return;}
 if(action==='saved'){savedOnly=!savedOnly;render();return;}
 if(action==='advance') {const a=state.applications.find(x=>x.id===id);if(role!=='business')return;try{Object.assign(a,advance(a,b.dataset.next));persist();render();toast(`Collaboration ${a.status.toLowerCase()}.`);}catch(err){toast(err.message);}return;}
 if(action==='reward-delivered'){const a=state.applications.find(x=>x.id===id);if(role!=='business'||a.status!=='Approved')return;a.rewardDelivered=true;persist();render();toast('Reward marked as delivered. No payment was sent by LocalPerks.');return;}
 if(action==='review'){const a=state.applications.find(x=>x.id===id),c=state.campaigns.find(x=>x.id===a.campaignId);b.disabled=true;b.textContent='Reviewing caption…';try{a.review=await reviewCaption(c,a.caption);persist();render();}catch(err){toast(err.message);b.disabled=false;b.textContent='✧ Review caption with Gemma';}return;}
 if(action==='enable-ai'){b.disabled=true;try{await enableAI(s=>{const t=$('#ai-status'),p=$('#ai-progress');if(t)t.textContent=s.message;if(p)p.value=s.progress;});b.textContent='Gemma is ready';toast('Gemma is ready on this device.');}catch(err){const t=$('#ai-status');if(t){t.textContent=err.message;t.classList.add('error');}b.disabled=false;b.textContent='Retry enabling Gemma';}return;}
 if(action==='export'){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='localperks-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Workspace exported.');return;}
 if(action==='reset'){openModal('Reset this demo workspace?',`<p class="modal-intro">This removes your saved opportunities, applications, and custom briefs from this browser. Export the workspace first if you want to keep them.</p><div class="actions"><button class="button secondary" data-action="settings">Keep workspace</button><button class="button" data-action="confirm-reset">Reset workspace</button></div>`);return;}
 if(action==='confirm-reset'){state={campaigns:structuredClone(seeds),applications:[],saved:[]};persist();modal.close();render();toast('Sample workspace reset.');}
});
document.addEventListener('input',event=>{if(event.target.id==='search'){search=event.target.value;renderCards();}});
document.addEventListener('change',event=>{if(event.target.id==='city'){city=event.target.value;renderCards();}if(event.target.id==='reward'){reward=event.target.value;renderCards();}});
document.addEventListener('submit',async event=>{
 const f=event.target;if(!['apply-form','brief-form','publish-form','work-form','memory-form'].includes(f.id))return;event.preventDefault();const data=Object.fromEntries(new FormData(f));
 if(f.id==='apply-form'){if(state.applications.some(x=>x.campaignId===f.dataset.id)){toast('An application already exists for this opportunity.');return;}state.applications.push({id:crypto.randomUUID(),campaignId:f.dataset.id,...data,status:'Applied',createdAt:new Date().toISOString()});persist();modal.close();view='workspace';render();toast('Application saved. Switch to business mode to accept it.');}
 if(f.id==='brief-form'){const isAI=event.submitter?.value==='ai';const buttons=f.querySelectorAll('button');buttons.forEach(x=>x.disabled=true);$('#brief-status').textContent=isAI?'Gemma is drafting your brief on this device…':'Preparing the manual template…';try{const result=isAI?await generateBrief(data):{title:`Create with ${data.business}`,description:data.idea,deliverables:[`Create one original ${data.platform} post about your experience at ${data.business}.`,'Agree on content format, usage rights, and posting details before starting.','Clearly disclose the collaboration and any compensation or gifts.'],questions:['Confirm the exact format and length.','Agree on any content usage beyond the original post.']};draft={...data,...result,ai:isAI};editDraft();}catch(err){$('#brief-status').textContent=err.message;$('#brief-status').classList.add('error');buttons.forEach(x=>x.disabled=false);}}
 if(f.id==='publish-form'){const deliverables=data.deliverables.split('\n').map(x=>x.trim()).filter(Boolean);if(!deliverables.length){toast('Add at least one deliverable.');return;}state.campaigns.unshift({...draft,...data,deliverables,id:crypto.randomUUID(),sample:false,art:draft.category==='Wellness'?'studio':draft.category==='Shops & makers'?'plant':'coffee',color:draft.category==='Wellness'?'#ddd4ee':draft.category==='Shops & makers'?'#d9e8cf':'#efcfad'});persist();modal.close();view='explore';category='All';search='';city='All cities';reward='All rewards';savedOnly=false;render();toast('Opportunity added to this demo workspace.');}
 if(f.id==='work-form'){const a=state.applications.find(x=>x.id===f.dataset.id);if(!safeURL(data.submission)){toast('Use a valid https:// or http:// work link.');return;}try{Object.assign(a,advance({...a,...data},'Work submitted'));persist();modal.close();render();toast('Work submitted. Switch to business mode to review it.');}catch(err){toast(err.message);}}
 if(f.id==='memory-form'){const c=state.campaigns.find(x=>x.id===data.campaignId),button=f.querySelector('button');button.disabled=true;$('#memory-status').textContent='Asking Backboard…';try{const response=await fetch('/api/memory',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaign:c,question:data.question})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Backboard request failed.');$('#memory-result').textContent=result.answer;$('#memory-status').textContent='Campaign memory updated on Backboard.';}catch(err){$('#memory-status').textContent=err.message;}finally{button.disabled=false;}}
});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
render();
fetch('/api/partners').then(r=>r.ok?r.json():null).then(p=>{if(p)partners=p;}).catch(()=>{});
